<?php

declare(strict_types=1);

namespace Architex\Platform\Planning;

use Architex\Platform\Audit\AuditService;
use Architex\Platform\Identity\Identifier;
use Architex\Platform\Project\ProjectContext;
use Architex\Platform\Project\ProjectPhase;
use Architex\Platform\Records\ProjectRecordService;
use DateTimeImmutable;
use PDO;
use PDOException;
use Throwable;

final readonly class TownPlanningService
{
    private const TYPES=['rezoning','consent_use','subdivision','consolidation','removal_restrictions','township_establishment','site_development_plan','other'];
    private const ENTRY_TYPES=['document','deadline','participation','condition','hearing','appeal','municipality_profile','fee','message'];
    private const ENTRY_STATUSES=['open','pending','complete','paid','unpaid','resolved','scheduled','received','responded','fulfilled','not_applicable'];

    public function __construct(private PDO $pdo){}

    /** @return list<array<string,mixed>> */
    public function list(string$organisationId,string$userId,?string$projectId):array
    {
        $this->member($organisationId,$userId);$params=['organisation'=>$organisationId];$where='organisation_id=UNHEX(:organisation)';
        if($projectId!==null){$projectId=$this->id($projectId,'planning_project_not_found');$this->project($organisationId,$projectId);$where.=' AND project_id=UNHEX(:project)';$params['project']=$projectId;}
        $statement=$this->pdo->prepare("SELECT LOWER(HEX(id)) FROM planning_applications WHERE $where ORDER BY created_at DESC,id DESC LIMIT 200");$statement->execute($params);$out=[];foreach($statement->fetchAll(PDO::FETCH_COLUMN)as$id)$out[]=$this->get($organisationId,$userId,(string)$id);return$out;
    }

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function create(string$organisationId,string$userId,string$membershipRole,array$input):array
    {
        $this->writer($organisationId,$userId,$membershipRole);$projectId=null;
        if(($input['projectId']??null)!==null&&$input['projectId']!==''){$projectId=$this->id($input['projectId'],'planning_project_not_found');$this->project($organisationId,$projectId);}
        $sources=$this->sources($input['sourceBasis']??null);$id=Identifier::generate();$values=['id'=>$id,'organisation'=>$organisationId,'project'=>$projectId,'number'=>$this->text($input['applicationNumber']??null,80,'planning_application_number_required'),'type'=>$this->choice($input['applicationType']??null,self::TYPES,'planning_application_type_invalid'),'title'=>$this->text($input['title']??null,220,'planning_title_required'),'municipality'=>$this->text($input['municipality']??null,220,'planning_municipality_required'),'property'=>$this->text($input['propertyReference']??null,220,'planning_property_reference_required'),'role'=>$this->role($input['responsibleRole']??null),'sources'=>$this->encode($sources),'user'=>$userId];
        try{$this->pdo->beginTransaction();$this->pdo->prepare('INSERT INTO planning_applications(id,organisation_id,project_id,application_number,application_type,title,municipality,property_reference,responsible_role,source_basis,created_by) VALUES(UNHEX(:id),UNHEX(:organisation),UNHEX(:project),:number,:type,:title,:municipality,:property,:role,:sources,UNHEX(:user))')->execute($values);$this->event($organisationId,$userId,$id,'created',null,'preparation','Application record created.','',['sourceBasis'=>$sources]);(new AuditService($this->pdo))->append($organisationId,$userId,'planning.application.created','planning_application',$id,['projectId'=>$projectId,'applicationNumber'=>$values['number'],'applicationType'=>$values['type'],'sourceBasis'=>$sources]);$this->pdo->commit();}catch(PDOException$e){if($this->pdo->inTransaction())$this->pdo->rollBack();if((string)$e->getCode()==='23000')throw new TownPlanningException('planning_application_number_exists');throw$e;}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}
        return$this->get($organisationId,$userId,$id);
    }

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function addEntry(string$organisationId,string$userId,string$membershipRole,string$applicationId,int$expectedVersion,array$input):array
    {
        $this->writer($organisationId,$userId,$membershipRole);$application=$this->draft($organisationId,$userId,$applicationId,$expectedVersion);$entryType=$this->choice($input['entryType']??null,self::ENTRY_TYPES,'planning_entry_type_invalid');$status=$this->choice($input['status']??null,self::ENTRY_STATUSES,'planning_entry_status_invalid');$dueAt=$this->date($input['dueAt']??null);$amount=$input['amountCents']??null;if($amount!==null&&(!is_int($amount)||$amount<0||$amount>9_000_000_000_000))throw new TownPlanningException('planning_entry_amount_invalid');$payload=$input['payload']??[];if(!is_array($payload))throw new TownPlanningException('planning_entry_payload_invalid');$id=Identifier::generate();$values=['id'=>$id,'organisation'=>$organisationId,'application'=>$applicationId,'type'=>$entryType,'title'=>$this->text($input['title']??null,220,'planning_entry_title_required'),'status'=>$status,'required'=>($input['required']??false)===true?1:0,'basis'=>$this->optional($input['basis']??'',500,'planning_entry_basis_invalid'),'due'=>$dueAt,'amount'=>$amount,'payload'=>$this->encode($payload),'user'=>$userId];
        try{$this->pdo->beginTransaction();$this->lockDraft($organisationId,$applicationId,$expectedVersion);$this->pdo->prepare('INSERT INTO planning_register_entries(id,organisation_id,application_id,entry_type,title,status,required_flag,basis,due_at,amount_cents,payload,created_by) VALUES(UNHEX(:id),UNHEX(:organisation),UNHEX(:application),:type,:title,:status,:required,:basis,:due,:amount,:payload,UNHEX(:user))')->execute($values);$this->bump($organisationId,$applicationId,$expectedVersion);$this->event($organisationId,$userId,$applicationId,'entry_added',$application['stage'],$application['stage'],$values['title'],'',['entryId'=>$id,'entryType'=>$entryType,'status'=>$status]);(new AuditService($this->pdo))->append($organisationId,$userId,'planning.entry.created','planning_register_entry',$id,['applicationId'=>$applicationId,'entryType'=>$entryType,'status'=>$status,'required'=>(bool)$values['required']]);$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}
        $entry=$this->entry($organisationId,$id);$entry['applicationVersion']=$expectedVersion+1;return$entry;
    }

    /** @return array<string,mixed> */
    public function submit(string$organisationId,string$userId,string$membershipRole,string$applicationId,int$expectedVersion,bool$humanConfirmed,string$professionalRole,string$reason,string$externalReference):array
    {
        $this->writer($organisationId,$userId,$membershipRole);if(!$humanConfirmed)throw new TownPlanningException('planning_submission_confirmation_required');$professionalRole=$this->role($professionalRole);$reason=$this->text($reason,500,'planning_submission_reason_required');$externalReference=$this->text($externalReference,180,'planning_external_reference_required');$application=$this->draft($organisationId,$userId,$applicationId,$expectedVersion);if($professionalRole!==$application['responsibleRole']||($application['projectId']!==null&&!$this->canActAs($organisationId,$userId,$application['projectId'],$professionalRole)))throw new TownPlanningException('planning_submission_role_denied');
        $documents=array_values(array_filter($application['entries'],static fn(array$e):bool=>$e['entryType']==='document'&&$e['status']==='complete'));$incomplete=array_values(array_filter($application['entries'],static fn(array$e):bool=>$e['required']&&(($e['entryType']==='document'&&$e['status']!=='complete')||($e['entryType']==='fee'&&!in_array($e['status'],['paid','not_applicable'],true)))));if($documents===[]||$incomplete!==[])throw new TownPlanningException('planning_submission_evidence_incomplete');
        $snapshot=['application'=>['id'=>$application['id'],'projectId'=>$application['projectId'],'applicationNumber'=>$application['applicationNumber'],'applicationType'=>$application['applicationType'],'title'=>$application['title'],'municipality'=>$application['municipality'],'propertyReference'=>$application['propertyReference'],'responsibleRole'=>$application['responsibleRole'],'sourceBasis'=>$application['sourceBasis'],'stage'=>'submission','status'=>'active','externalReference'=>$externalReference],'entries'=>$application['entries'],'professionalConfirmation'=>['humanConfirmed'=>true,'professionalRole'=>$professionalRole,'reason'=>$reason,'userId'=>$userId],'externalBoundary'=>['handoffRecorded'=>true,'authorityAcceptanceClaimed'=>false,'approvalClaimed'=>false,'notificationSentByArchitex'=>false]];$json=$this->encode($snapshot);$sha=hash('sha256',$json);$recordId=null;$project=$application['projectId']===null?null:$this->project($organisationId,$application['projectId']);
        try{$this->pdo->beginTransaction();$this->lockDraft($organisationId,$applicationId,$expectedVersion);if($project!==null)$recordId=(new ProjectRecordService($this->pdo))->issue(new ProjectContext($organisationId,$userId,$application['projectId'],$membershipRole),ProjectPhase::from($project['currentPhase']),'town_planning','planning_submission',$application['applicationNumber'].' '.$application['title'],'issued',['applicationId'=>$applicationId,'externalReference'=>$externalReference,'snapshotSha256'=>$sha,'authorityAcceptanceClaimed'=>false,'approvalClaimed'=>false],['required'=>true,'humanApprovalConfirmed'=>true,'approvedBy'=>$userId,'professionalRole'=>$professionalRole,'reason'=>$reason]);$update=$this->pdo->prepare("UPDATE planning_applications SET stage='submission',status='active',version=version+1,external_reference=:external,external_submission_claimed=1,submission_reason=:reason,snapshot_payload=:snapshot,snapshot_sha256=:sha,project_record_id=UNHEX(:record),submitted_by=UNHEX(:user),submitted_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation) AND version=:version AND status='draft'");$update->execute(['external'=>$externalReference,'reason'=>$reason,'snapshot'=>$json,'sha'=>$sha,'record'=>$recordId,'user'=>$userId,'id'=>$applicationId,'organisation'=>$organisationId,'version'=>$expectedVersion]);if($update->rowCount()!==1)throw new TownPlanningException('planning_version_conflict');$this->event($organisationId,$userId,$applicationId,'submission_recorded',$application['stage'],'submission',$reason,$externalReference,['snapshotSha256'=>$sha,'projectRecordId'=>$recordId,'authorityAcceptanceClaimed'=>false]);(new AuditService($this->pdo))->append($organisationId,$userId,'planning.application.submitted','planning_application',$applicationId,['externalReference'=>$externalReference,'snapshotSha256'=>$sha,'projectRecordId'=>$recordId,'professionalRole'=>$professionalRole,'authorityAcceptanceClaimed'=>false,'approvalClaimed'=>false]);$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}
        return$this->get($organisationId,$userId,$applicationId);
    }

    /** @return array<string,mixed> */
    public function get(string$organisationId,string$userId,string$applicationId):array
    {
        $this->member($organisationId,$userId);$applicationId=$this->id($applicationId,'planning_application_not_found');$statement=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,LOWER(HEX(project_id)) project_id,application_number,application_type,title,municipality,property_reference,responsible_role,source_basis,stage,status,version,external_reference,external_submission_claimed,submission_reason,snapshot_payload,snapshot_sha256,LOWER(HEX(project_record_id)) project_record_id,LOWER(HEX(submitted_by)) submitted_by,submitted_at,created_at FROM planning_applications WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation)");$statement->execute(['id'=>$applicationId,'organisation'=>$organisationId]);$row=$statement->fetch();if(!is_array($row))throw new TownPlanningException('planning_application_not_found');$snapshot=$row['snapshot_payload']===null?null:json_decode((string)$row['snapshot_payload'],true,64,JSON_THROW_ON_ERROR);if($snapshot!==null&&!hash_equals((string)$row['snapshot_sha256'],hash('sha256',$this->encode($snapshot))))throw new TownPlanningException('planning_integrity_failed');
        $entries=$this->entries($organisationId,$applicationId);$events=$this->events($organisationId,$applicationId);$counts=array_fill_keys(self::ENTRY_TYPES,0);foreach($entries as$entry)$counts[$entry['entryType']]++;return['id'=>$row['id'],'projectId'=>$row['project_id'],'applicationNumber'=>$row['application_number'],'applicationType'=>$row['application_type'],'title'=>$row['title'],'municipality'=>$row['municipality'],'propertyReference'=>$row['property_reference'],'responsibleRole'=>$row['responsible_role'],'sourceBasis'=>json_decode((string)$row['source_basis'],true,64,JSON_THROW_ON_ERROR),'stage'=>$row['stage'],'status'=>$row['status'],'version'=>(int)$row['version'],'externalReference'=>$row['external_reference'],'externalSubmissionClaimed'=>(bool)$row['external_submission_claimed'],'authorityAcceptanceClaimed'=>false,'approvalClaimed'=>in_array($row['status'],['approved'],true),'submissionReason'=>$row['submission_reason'],'snapshot'=>$snapshot,'snapshotSha256'=>$row['snapshot_sha256'],'projectRecordId'=>$row['project_record_id'],'submittedBy'=>$row['submitted_by'],'submittedAt'=>$row['submitted_at'],'createdAt'=>$row['created_at'],'entries'=>$entries,'events'=>$events,'registerCounts'=>$counts];
    }

    /** @return list<array<string,mixed>> */private function entries(string$o,string$a):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,entry_type,title,status,required_flag,basis,DATE_FORMAT(due_at,'%Y-%m-%dT%H:%i:%s.%fZ') due_at,amount_cents,payload,LOWER(HEX(created_by)) created_by,DATE_FORMAT(created_at,'%Y-%m-%dT%H:%i:%s.%fZ') created_at FROM planning_register_entries WHERE organisation_id=UNHEX(:organisation) AND application_id=UNHEX(:application) ORDER BY created_at,id");$s->execute(['organisation'=>$o,'application'=>$a]);$out=[];foreach($s->fetchAll()as$r)$out[]=$this->mapEntry($r);return$out;}
    /** @return array<string,mixed> */private function entry(string$o,string$id):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,entry_type,title,status,required_flag,basis,DATE_FORMAT(due_at,'%Y-%m-%dT%H:%i:%s.%fZ') due_at,amount_cents,payload,LOWER(HEX(created_by)) created_by,DATE_FORMAT(created_at,'%Y-%m-%dT%H:%i:%s.%fZ') created_at FROM planning_register_entries WHERE organisation_id=UNHEX(:organisation) AND id=UNHEX(:id)");$s->execute(['organisation'=>$o,'id'=>$id]);$r=$s->fetch();if(!is_array($r))throw new TownPlanningException('planning_entry_not_found');return$this->mapEntry($r);}
    /** @param array<string,mixed> $r @return array<string,mixed> */private function mapEntry(array$r):array{return['id'=>$r['id'],'entryType'=>$r['entry_type'],'title'=>$r['title'],'status'=>$r['status'],'required'=>(bool)$r['required_flag'],'basis'=>$r['basis'],'dueAt'=>$r['due_at'],'amountCents'=>$r['amount_cents']===null?null:(int)$r['amount_cents'],'payload'=>json_decode((string)$r['payload'],true,64,JSON_THROW_ON_ERROR),'createdBy'=>$r['created_by'],'createdAt'=>$r['created_at']];}
    /** @return list<array<string,mixed>> */private function events(string$o,string$a):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,event_type,from_stage,to_stage,reason,external_reference,payload,LOWER(HEX(actor_user_id)) actor_user_id,DATE_FORMAT(created_at,'%Y-%m-%dT%H:%i:%s.%fZ') created_at FROM planning_application_events WHERE organisation_id=UNHEX(:organisation) AND application_id=UNHEX(:application) ORDER BY created_at,id");$s->execute(['organisation'=>$o,'application'=>$a]);$out=[];foreach($s->fetchAll()as$r)$out[]=['id'=>$r['id'],'eventType'=>$r['event_type'],'fromStage'=>$r['from_stage'],'toStage'=>$r['to_stage'],'reason'=>$r['reason'],'externalReference'=>$r['external_reference'],'payload'=>json_decode((string)$r['payload'],true,64,JSON_THROW_ON_ERROR),'actorUserId'=>$r['actor_user_id'],'createdAt'=>$r['created_at']];return$out;}
    /** @param array<string,mixed> $payload */private function event(string$o,string$u,string$a,string$t,?string$f,?string$to,string$r,string$x,array$payload):void{$this->pdo->prepare('INSERT INTO planning_application_events(id,organisation_id,application_id,event_type,from_stage,to_stage,reason,external_reference,payload,actor_user_id) VALUES(UNHEX(:id),UNHEX(:organisation),UNHEX(:application),:type,:from_stage,:to_stage,:reason,:external,:payload,UNHEX(:user))')->execute(['id'=>Identifier::generate(),'organisation'=>$o,'application'=>$a,'type'=>$t,'from_stage'=>$f,'to_stage'=>$to,'reason'=>$r,'external'=>$x===''?null:$x,'payload'=>$this->encode($payload),'user'=>$u]);}
    /** @return array<string,mixed> */private function draft(string$o,string$u,string$a,int$v):array{$app=$this->get($o,$u,$a);if($app['status']!=='draft')throw new TownPlanningException('planning_application_submitted');if($v<1||$app['version']!==$v)throw new TownPlanningException('planning_version_conflict');return$app;}
    private function lockDraft(string$o,string$a,int$v):void{$s=$this->pdo->prepare("SELECT version,status FROM planning_applications WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation) FOR UPDATE");$s->execute(['id'=>$a,'organisation'=>$o]);$r=$s->fetch();if(!is_array($r))throw new TownPlanningException('planning_application_not_found');if($r['status']!=='draft')throw new TownPlanningException('planning_application_submitted');if((int)$r['version']!==$v)throw new TownPlanningException('planning_version_conflict');}
    private function bump(string$o,string$a,int$v):void{$s=$this->pdo->prepare("UPDATE planning_applications SET version=version+1 WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation) AND version=:version AND status='draft'");$s->execute(['id'=>$a,'organisation'=>$o,'version'=>$v]);if($s->rowCount()!==1)throw new TownPlanningException('planning_version_conflict');}
    /** @return array{currentPhase:string,leadProfessionalRole:string,createdBy:string} */private function project(string$o,string$p):array{$s=$this->pdo->prepare("SELECT current_phase currentPhase,lead_professional_role leadProfessionalRole,LOWER(HEX(created_by)) createdBy FROM projects WHERE id=UNHEX(:project) AND organisation_id=UNHEX(:organisation)");$s->execute(['project'=>$p,'organisation'=>$o]);$r=$s->fetch();if(!is_array($r))throw new TownPlanningException('planning_project_not_found');return$r;}
    private function canActAs(string$o,string$u,string$p,string$r):bool{$project=$this->project($o,$p);if(hash_equals($project['createdBy'],$u)&&$project['leadProfessionalRole']===$r)return true;$s=$this->pdo->prepare("SELECT 1 FROM project_team_members WHERE organisation_id=UNHEX(:organisation) AND project_id=UNHEX(:project) AND user_id=UNHEX(:user) AND status='active' AND discipline=:role");$s->execute(['organisation'=>$o,'project'=>$p,'user'=>$u,'role'=>$r]);return$s->fetchColumn()!==false;}
    private function writer(string$o,string$u,string$r):void{if(!in_array($r,['owner','admin','member'],true))throw new TownPlanningException('planning_permission_denied');$this->member($o,$u);}
    private function member(string$o,string$u):void{$this->id($o,'planning_permission_denied');$this->id($u,'planning_permission_denied');$s=$this->pdo->prepare("SELECT 1 FROM organisation_memberships WHERE organisation_id=UNHEX(:organisation) AND user_id=UNHEX(:user) AND status='active'");$s->execute(['organisation'=>$o,'user'=>$u]);if($s->fetchColumn()===false)throw new TownPlanningException('planning_permission_denied');}
    /** @return list<array{title:string,url:string,retrievedAt:string}> */private function sources(mixed$v):array{if(!is_array($v)||$v===[]||count($v)>20)throw new TownPlanningException('planning_source_basis_required');$out=[];foreach($v as$s){if(!is_array($s))throw new TownPlanningException('planning_source_basis_invalid');$url=$this->text($s['url']??null,1000,'planning_source_url_required');if(filter_var($url,FILTER_VALIDATE_URL)===false||!in_array(parse_url($url,PHP_URL_SCHEME),['http','https'],true))throw new TownPlanningException('planning_source_url_invalid');$date=$this->text($s['retrievedAt']??null,10,'planning_source_date_required');$parsed=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$parsed||$parsed->format('Y-m-d')!==$date)throw new TownPlanningException('planning_source_date_invalid');$out[]=['title'=>$this->text($s['title']??null,220,'planning_source_title_required'),'url'=>$url,'retrievedAt'=>$date];}return$out;}
    private function date(mixed$v):?string{if($v===null||$v==='')return null;if(!is_string($v))throw new TownPlanningException('planning_entry_due_at_invalid');try{return(new DateTimeImmutable($v))->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s.u');}catch(Throwable){throw new TownPlanningException('planning_entry_due_at_invalid');}}
    private function id(mixed$v,string$e):string{if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new TownPlanningException($e);return strtolower($v);}private function role(mixed$v):string{$v=$this->text($v,80,'planning_role_invalid');if(preg_match('/\A[a-z][a-z0-9_]{1,79}\z/',$v)!==1)throw new TownPlanningException('planning_role_invalid');return$v;}
    /** @param list<string> $a */private function choice(mixed$v,array$a,string$e):string{if(!is_string($v)||!in_array($v,$a,true))throw new TownPlanningException($e);return$v;}private function text(mixed$v,int$m,string$e):string{$v=is_string($v)?trim($v):'';if($v===''||mb_strlen($v)>$m)throw new TownPlanningException($e);return$v;}private function optional(mixed$v,int$m,string$e):string{$v=is_string($v)?trim($v):'';if(mb_strlen($v)>$m)throw new TownPlanningException($e);return$v;}private function encode(mixed$v):string{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);}
}
